public static File lastFileModified(String dir){
  File fl=new File(dir);
  File[] files=fl.listFiles(File::isFile);
  if (files == null) {
    return null;
  }
  long lastMod=Long.MIN_VALUE;
  File choice=null;
  for (  File file : files) {
    if (file.lastModified() > lastMod) {
      choice=file;
      lastMod=file.lastModified();
    }
  }
  return choice;
}
